class Base { declare seen: number | undefined; set z(v: number) { this.seen = v; } }
export class A extends Base { x: number | undefined; y: number = 1; }
export class B extends Base { // @ts-expect-error
  z: number = 2; }
export function keys(): string { return Object.keys(new A()).join(",") + " " + Object.keys(new B()).join(","); }
